    {
      "path": "lib/state.mjs",
      "content": "/**\n * lib/state.mjs —— 插件的\"家\"与配置\n * ============================================================================\n * 规矩（抄 whale_craft）：**配置、凭证、报告、日志都放插件自己的家** ——\n * `$DSH_HOME/bili-duty/`，**绝不写进插件包目录**（装进 node_modules 后可能只读、升级也会被覆盖）。\n *\n * 还有一件小事但很要紧：vendored 的 `mcp_server.py` 里，凭证路径是\n * `Path(__file__).parent / \"bili_credential.json\"` —— 所以**运行时要把脚本拷到家目录里再跑**，\n * 这样凭证才会落在家的目录，而不是插件包里。\n * ============================================================================\n */\nimport { existsSync, mkdirSync, readFileSync, writeFileSync, copyFileSync } from 'node:fs'\nimport { createHash as nodeCreateHash } from 'node:crypto'\nimport { createHash } from 'node:crypto'\nimport { join } from 'node:path'\nimport { homedir } from 'node:os'\n\n/**\n * 谷时窗口（北京时间）—— 想改就改这一处。\n * ⭐ 官方口径（2026-09-10 起的新定价）：**高峰 = 工作日 9:00–12:00 与 14:00–18:00，其余全是谷时**\n *    ⇒ 12:00–14:00（夹在两个高峰之间）✓、18:00 之后的一整晚 ✓、以及**整个周末** ✓ 都便宜。\n * ⚠️ 我们原来写的 00:30–08:30 是 DeepSeek **早年**的错峰优惠时段，**已经过时** ✗\n *    —— 2026-10-14 使用者在\"陌生人验收\"里问「晚上峰谷真的是12点半才开始的吗」才查出来 ✓。\n */\nexport const WINDOWS = {\n  noon: { label: '中午谷时', start: '12:00', end: '14:00' },\n  night: { label: '晚上/夜间谷时', start: '18:00', end: '09:00' },\n}\n\n/**\n * ⭐ 2026-10-14 真机上踩到的坑（dsh 只留一句 `warning: 1 entry did not activate` + 堆栈）：\n *    `ctx.get('dshHomePath')` 返回的是**函数**，不是字符串！\n *    形状：`dshHomePath(...segments) => join(resolveDshHome(), ...segments)`（whale_craft 就是这么用的）。\n *    我一开始当字符串用（`String(p)`），路径就成了「函数源码 + \\bili-duty」⇒ mkdir ENOENT ⇒ apply 抛错 ⇒ 插件不激活。\n */\nexport function stateDirOf(ctx) {\n  let dir = ''\n  try {\n    const p = ctx?.get?.('dshHomePath')\n    if (typeof p === 'function') {\n      const v = p('bili-duty')                       // ← 函数形态：把目录名传进去\n      if (v) dir = String(v)\n    } else if (typeof p === 'string' && p) {\n      dir = join(p, 'bili-duty')\n    }\n  } catch { /* 拿不到就用下面的兜底 */ }\n  if (!dir) dir = join(process.env.DSH_HOME || join(homedir(), '.dsh'), 'bili-duty')\n  mkdirSync(dir, { recursive: true })\n  return dir\n}\n\nexport function readJson(file, fallback) {\n  try { return JSON.parse(readFileSync(file, 'utf8')) } catch { return fallback }\n}\n\nexport function writeJson(file, value) {\n  writeFileSync(file, JSON.stringify(value, null, 2), 'utf8')\n}\n\n/**\n * 把 vendored 的脚本铺进家里。\n *\n * ⭐ 2026-10-22（用户 @俺爱啃猪蹄子 指出策略不一致）：以前是\"内容不一样就覆盖\" ⇒ **用户改过的直接丢** ✗，\n *    而章程 duty.md 是\"改过就保留\" —— 同一个插件两套规矩，很怪。\n *    现在改成**记住\"上次我们发出去那份的指纹\"**（`.shipped-<文件名>.sha`）：\n *      · 家里那份 == 我们发的 ⇒ 正常升级覆盖 ✓\n *      · 家里那份 ≠ 我们发的 ⇒ **说明用户改过** ⇒ 不覆盖，新版写到 `<文件>.new` 并提示 ✓\n *      · 没有指纹（老版本升级上来）⇒ 按老行为覆盖一次并记指纹（从这一版起才有\"改过\"的概念）✓\n */\nexport function ensureHomeFiles(pluginDir, stateDir, log = () => {}) {\n  const copies = [\n    [join(pluginDir, 'vendor', 'bilibili-mcp', 'mcp_server.py'), join(stateDir, 'mcp_server.py')],\n    [join(pluginDir, 'lib', 'asr.py'), join(stateDir, 'asr.py')],\n    [join(pluginDir, 'lib', 'favops.py'), join(stateDir, 'favops.py')],\n  ]\n  const sha = (buf) => {\n    try { return nodeCreateHash('sha256').update(buf).digest('hex') } catch { return '' }\n  }\n  for (const [from, to] of copies) {\n    try {\n      if (!existsSync(from)) { log(`缺文件：${from}`); continue }\n      const incoming = readFileSync(from, 'utf8')\n      const markFile = join(stateDir, '.shipped-' + to.split(/[\\\\/]/).pop() + '.sha')\n      const shipped = existsSync(markFile) ? readFileSync(markFile, 'utf8').trim() : ''\n      const writeMark = (txt) => { try { writeFileSync(markFile, sha(Buffer.from(txt, 'utf8')), 'utf8') } catch { /* 记不上就下次再说 */ } }\n      if (!existsSync(to)) {\n        copyFileSync(from, to); writeMark(incoming); log(`已铺好：${to}`); continue\n      }\n      const onDisk = readFileSync(to, 'utf8')\n      if (onDisk === incoming) { if (!shipped) writeMark(incoming); continue }   // 本来就是同一份\n      // ⭐⭐ 2.1.0（2026-10-24 实证）：剩下两种情况的处理可以并成一条 ——\n      //    这几个文件是**我们发的运行时代码**（mcp_server.py / asr.py / favops.py），\n      //    用户改过也不该拦着升级：否则\"宿主新、Python 侧旧\"，新工具根本不出现 ✗\n      //    （今天就这么栽的：家目录那份停在 11:50，值班轮里说\"没有 bili_cover 这个工具\"）\n      //    ⇒ **先备份 .bak-<时间戳>，再覆盖**，改了什么都能自己捞回来 ✓\n      const stamp = new Date().toISOString().replace(/[:.]/g, \"-\").slice(0, 19)\n      const bak = to + \".bak-\" + stamp\n      try { copyFileSync(to, bak) } catch { /* 备份不了也继续，原件在插件包里 */ }\n      copyFileSync(from, to)\n      writeMark(incoming)\n      log(`已覆盖：${to}（旧的那份备份在 ${bak}）`)\n    } catch (e) { log(`铺 ${to} 失败：${e?.message ?? e}`) }\n  }\n}\n\n/**\n * 值班章程（prompts/duty.md）放在哪一份 —— 家里那份优先，没有才用插件里那份。\n * （家里那份由下面的 ensureCharter 保证铺好）\n */\nexport function charterPath(pluginDir, stateDir) {\n  const home = join(stateDir, 'duty.md')\n  try { if (existsSync(home)) return home } catch { /* 兜底：用插件里那份 */ }\n  return join(pluginDir, 'prompts', 'duty.md')\n}\n\n/**\n * ⭐ 值班章程怎么升级 —— 2026-10-17 审查里的 M6 就是这里。\n *    老规矩（index.js 里比 mtime）：家里那份比 shipped 新 ⇒ 听使用者的。听着合理，实际是一把**单向锁**：\n *    使用者只要改过章程一个字，家里那份就永远比 shipped 新 ⇒ 插件后续版本改进的章程\n *    （0.1.5 的注入防护、空输出定义恰好就写在章程里）**永远进不来** ✗。\n *    改成记账制 —— 上次铺的是哪一版（sha256）记在 charter.sha256：\n *      · 家里那份 === 我们上次铺的 ⇒ 他没动过 ⇒ 直接用 shipped 覆盖（升级 ✓）\n *      · 家里那份变过      ⇒ 他改过 ⇒ **一个字都不动**，新版另存 duty.md.new 让他自己合 ✓\n *      · 没有账本（带账本的第一个版本刚跑起来）⇒ 分不清「没改只是版本旧」和「改过」，\n *        按「改过」处理 —— 宁可让他手动合一次，也不能偷偷吃掉他的改动 ✓\n */\nexport function ensureCharter(pluginDir, stateDir, log = () => {}) {\n  const shipped = join(pluginDir, 'prompts', 'duty.md')\n  const home = join(stateDir, 'duty.md')\n  const ledger = join(stateDir, 'charter.sha256')\n  const fresh = join(stateDir, 'duty.md.new')\n  const readIf = (f) => { try { return readFileSync(f, 'utf8') } catch { return '' } }\n  try {\n    if (!existsSync(shipped)) { log(`缺文件：${shipped}`); return }\n    const sha = (s) => createHash('sha256').update(s, 'utf8').digest('hex')\n    const newText = readFileSync(shipped, 'utf8')\n    const hShip = sha(newText)\n    const hLast = readIf(ledger).trim()\n    if (!existsSync(home)) {\n      writeFileSync(home, newText, 'utf8'); writeFileSync(ledger, hShip, 'utf8')\n      log('已铺好值班章程')\n      return\n    }\n    const hHome = sha(readFileSync(home, 'utf8'))\n    if (hHome === hShip) {                              // 家里那份就是最新版（他可能只是没动过）\n      if (hLast !== hShip) writeFileSync(ledger, hShip, 'utf8')\n      return\n    }\n    if (!hLast || hHome !== hLast) {                    // 他改过（或没账本、分不清）⇒ 只另存新版\n      if (hShip !== hLast && readIf(fresh) !== newText) {\n        writeFileSync(fresh, newText, 'utf8')\n        log(`值班章程有新版、但家里那份你改过 ⇒ 新版另存为 ${fresh}，自己合一下`)\n      }\n      return\n    }\n    writeFileSync(home, newText, 'utf8'); writeFileSync(ledger, hShip, 'utf8')   // 他没动过 ⇒ 直接升级\n    log('值班章程已更新到插件里这一版')\n  } catch (e) { log(`铺值班章程失败：${e?.message ?? e}`) }\n}\n\n/** 'HH:MM' → 当天的分钟数 */\nfunction minutesOf(hhmm) {\n  const m = /^(\\d{1,2}):(\\d{2})$/.exec(String(hhmm).trim())\n  if (!m) return null\n  return Number(m[1]) * 60 + Number(m[2])\n}\n\n/**\n * 官方定价口径是**北京时间**（见上面 WINDOWS 的注释），\n * 所以取\"现在几点\"必须换算到 UTC+8，**不能直接用 `now.getHours()`** ——\n * 那个读的是**运行机器自己的时区**：部署在 UTC 的机器上会整整差 8 小时，\n * 谷时窗口全部错位（issue #71）。\n *\n * 中国不实行夏令时，UTC+8 是固定偏移，所以直接按偏移算即可，\n * 不依赖 `Intl` 时区数据库（某些精简 Node/Electron 构建里可能缺）。\n */\nconst BEIJING_OFFSET_MINUTES = 8 * 60\n\n/** 把一个时刻换算成北京时间的 { 分钟数, 星期几(0=周日) } */\nfunction beijingClock(now) {\n  const shifted = new Date(now.getTime() + BEIJING_OFFSET_MINUTES * 60 * 1000)\n  return {\n    // 用 getUTC* 读那个\"平移过的\"时刻 ⇒ 得到的就是北京时间的墙上时间\n    minutes: shifted.getUTCHours() * 60 + shifted.getUTCMinutes(),\n    weekday: shifted.getUTCDay(),\n  }\n}\n\n/**\n * 现在在不在这个窗口里（支持跨零点，比如 23:00–02:00）。\n *\n * ⚠️ 按**北京时间**判断，不是本机时区（issue #71）。\n * ⚠️ 另外：官方口径里**整个周末都是谷时**，所以周六/周日一律返回 true ——\n *    以前这里没判断周末，导致周末的 9–12 / 14–18 被当成高峰、该跑的时候没跑。\n */\nexport function inWindow(now, win) {\n  const start = minutesOf(win.start); const end = minutesOf(win.end)\n  if (start === null || end === null) return false\n  const { minutes: cur, weekday } = beijingClock(now)\n  // 周末全天谷时\n  if (weekday === 0 || weekday === 6) return true\n  return start <= end ? (cur >= start && cur < end) : (cur >= start || cur < end)\n}\n\n/**\n * 本地日期 YYYY-MM-DD。\n *\n * 这里刻意保留**本机时区**：它用于「今天跑过没有」这类按使用者日历翻页的判断，\n * 用本机日期比用北京时间更符合直觉（否则跨时区的使用者在晚上 8 点就被翻页）。\n * 与 `inWindow` 的北京时间口径是两个不同用途，别混。\n */\nexport function dayKey(now = new Date()) {\n  const p = (n) => String(n).padStart(2, '0')\n  return `${now.getFullYear()}-${p(now.getMonth() + 1)}-${p(now.getDate())}`\n}\n\n/**\n * 判重表里的日期格 → YYYY-MM-DD；认不出来返回 null\n * ⭐ 模型会自己写短日期（`10-23`、`2026/10/23`、带时间的）⇒ 这里宽容地认（#133）：\n *   没写年份就按今年补；补出来比今天还晚（比如一月份读到 `12-31`）⇒ 算去年\n */\nexport function seenDay(raw, now = new Date()) {\n  const m = /^(?:(\\d{4})[-/.])?(\\d{1,2})[-/.](\\d{1,2})(?:[ T]\\d{1,2}:\\d{2}(?::\\d{2})?)?$/.exec(String(raw ?? '').trim())\n  if (!m) return null\n  const mo = Number(m[2]); const d = Number(m[3])\n  let y = m[1] ? Number(m[1]) : now.getFullYear()\n  const valid = (yy) => { const t = new Date(yy, mo - 1, d); return t.getFullYear() === yy && t.getMonth() === mo - 1 && t.getDate() === d }\n  if (!valid(y)) return null\n  const p = (n) => String(n).padStart(2, '0')\n  if (!m[1] && `${y}-${p(mo)}-${p(d)}` > dayKey(now)) {\n    y -= 1\n    if (!valid(y)) return null   // 02-29 遇上去年不是闰年\n  }\n  return `${y}-${p(mo)}-${p(d)}`\n}\n\n"
    },
    {
      "path": "lib/mcp.mjs",
      "content": "/**\n * lib/mcp.mjs —— 一个极小的 MCP stdio 客户端（只做我们需要的三件事）\n * ============================================================================\n * 为什么不用 `@deepseek-ai/dsh-mcp-client`：那是个\"把 MCP 挂成 dsh 工具\"的完整插件，\n * 而我们要的是**插件内部自己起这个 Python MCP**（用户选了 A 方案：装完就能用，\n * Python 路径和登录都在设置页里，不用去改 profile 的 patch）。\n *\n * 协议就三句话：`initialize` → `notifications/initialized` → `tools/call`，\n * stdio 上是**一行一个 JSON-RPC**。\n * ============================================================================\n */\nimport { spawn } from 'node:child_process'\nimport { readFileSync } from 'node:fs'\n\n// 报给对端的身份：版本号**从 package.json 读**，别手写（手写的那份永远追不上发版）\nconst PKG = (() => { try { return JSON.parse(readFileSync(new URL('../package.json', import.meta.url), 'utf8')) } catch { return {} } })()\n\nexport class McpClient {\n  constructor({ command, args = [], cwd, env, log = () => {} }) {\n    this.cfg = { command, args, cwd, env, log }\n    this.proc = null\n    this.buf = ''\n    this.nextId = 1\n    this.pending = new Map()\n    this.stderr = ''\n    this.starting = null\n  }\n\n  get running() { return Boolean(this.proc) }\n\n  async start() {\n    if (this.proc) return\n    if (this.starting) return this.starting\n    this.starting = (async () => {\n      const { command, args, cwd, env, log } = this.cfg\n      this.proc = spawn(command, args, {\n        cwd,\n        env: { ...process.env, ...(env || {}) },\n        stdio: ['pipe', 'pipe', 'pipe'],\n        windowsHide: true,\n      })\n      this.proc.stdout.setEncoding('utf8')\n      this.proc.stdout.on('data', (chunk) => this.#onData(chunk))\n      this.proc.stderr.setEncoding('utf8')\n      this.proc.stderr.on('data', (c) => { this.stderr = (this.stderr + c).slice(-4000) })\n      this.proc.on('error', (e) => log(`MCP 子进程启动失败：${e?.message ?? e}`))\n      this.proc.on('exit', (code) => {\n        log(`MCP 子进程退出（code=${code}）`)\n        for (const [, p] of this.pending) p.reject(new Error(`MCP 子进程退出（code=${code}）${this.stderr ? '：' + this.stderr.slice(-300) : ''}`))\n        this.pending.clear()\n        this.proc = null\n      })\n      await this.#request('initialize', {\n        protocolVersion: '2024-11-05',\n        capabilities: {},\n        clientInfo: { name: PKG.name || 'dsh-bili-scroll', version: PKG.version || '0.0.0' },\n      })\n      this.#notify('notifications/initialized', {})\n      log('MCP 已就绪')\n    })()\n    try { await this.starting } finally { this.starting = null }\n  }\n\n  stop() {\n    try { this.proc?.kill() } catch { /* 已经没了 */ }\n    this.proc = null\n  }\n\n  /** 调一个 MCP 工具：能解析成 JSON 就返回对象，否则返回字符串 */\n  async call(name, args = {}, opts = {}) {\n    return (await this.callRaw(name, args, opts)).json\n  }\n\n  /** 同 call，但保留图片块：返回 { json, images }，images 每项是 { data, mimeType } */\n  async callRaw(name, args = {}, { timeoutMs = 180000, signal } = {}) {\n    await this.start()\n    const result = await this.#request('tools/call', { name, arguments: args }, timeoutMs, signal)\n    const blocks = result?.content ?? []\n    const text = blocks.map((c) => c?.text ?? '').filter(Boolean).join('\\n').trim()\n    if (result?.isError) throw new Error(text || `MCP 工具 ${name} 报错`)\n    const images = blocks\n      .filter((c) => c?.type === 'image' && c?.data)\n      .map((c) => ({ data: c.data, mimeType: c.mimeType || c.mime_type || 'image/jpeg' }))\n    let json = {}\n    try { json = text ? JSON.parse(text) : {} } catch { json = text }\n    return { json, images }\n  }\n\n  #onData(chunk) {\n    this.buf += chunk\n    let idx\n    while ((idx = this.buf.indexOf('\\n')) >= 0) {\n      const line = this.buf.slice(0, idx).trim()\n      this.buf = this.buf.slice(idx + 1)\n      if (!line) continue\n      let msg\n      try { msg = JSON.parse(line) } catch { continue }   // 非 JSON 行（有些库会往 stdout 打日志）忽略\n      if (msg.id !== undefined && this.pending.has(msg.id)) {\n        const p = this.pending.get(msg.id)\n        this.pending.delete(msg.id)\n        if (msg.error) p.reject(new Error(msg.error?.message ? String(msg.error.message) : JSON.stringify(msg.error)))\n        else p.resolve(msg.result)\n      }\n    }\n  }\n\n  #send(obj) {\n    if (!this.proc?.stdin?.writable) throw new Error('MCP 子进程不在运行')\n    this.proc.stdin.write(JSON.stringify(obj) + '\\n')\n  }\n\n  #notify(method, params) { this.#send({ jsonrpc: '2.0', method, params }) }\n\n  #request(method, params, timeoutMs = 60000, signal) {\n    const id = this.nextId++\n    return new Promise((resolve, reject) => {\n      if (signal?.aborted) {\n        reject(new Error(`MCP ${method} 已取消`))\n        return\n      }\n      const cleanup = () => {\n        clearTimeout(timer)\n        this.pending.delete(id)\n        signal?.removeEventListener?.('abort', onAbort)\n      }\n      const onAbort = () => {\n        cleanup()\n        reject(new Error(`MCP ${method} 已取消`))\n      }\n      const timer = setTimeout(() => {\n        cleanup()\n        reject(new Error(`MCP ${method} 超时（${timeoutMs}ms）${this.stderr ? '：' + this.stderr.slice(-200) : ''}`))\n      }, timeoutMs)\n      this.pending.set(id, {\n        resolve: (v) => { cleanup(); resolve(v) },\n        reject: (e) => { cleanup(); reject(e) },\n      })\n      signal?.addEventListener?.('abort', onAbort, { once: true })\n      try { this.#send({ jsonrpc: '2.0', id, method, params }) } catch (e) {\n        cleanup(); reject(e)\n      }\n    })\n  }\n}\n"
    },
