      "path": "profile-template/bili-duty/cordis.patch.yml",
      "content": "# ============================================================================\n# 「刷B站」值班轮专用 profile（2026-10-24 安全加固 · 对齐 issue #96 / PR #97 的思路）\n# ============================================================================\n# 为什么单独建一个 profile：\n#   值班轮是**无人值守**的一轮。原来它跑在 stock 的 headless profile 上，那个 profile\n#   只关了 hmr / credentials / authorization / deepseek-account —— 工具一个没动。\n#   于是那一轮除了 B站 MCP 的几个只读工具，还带着整台电脑：\n#   tool-fs（任意读写）、tool-pwsh（任意命令）、tool-fs-search（全局搜）、\n#   tool-web / web-fetch-http（抓任意 URL）、subagent / workflow（绕开限制）、skill（读文件）。\n#   ⚠️ DSH 的沙箱只限制「写」，**读是不受限的** ⇒ 它能读 ~/.dsh/sessions/**（全部会话记录）、\n#   凭证、工作区；而 B站 MCP 进程跑在沙箱外，是现成的外发通道。\n#   ⇒ 修法不是\"叮嘱它别读\"，而是**不给它文件系统**；写日报/判重表/归档改走固定路径的窄口 MCP。\n#\n# 下面这些 id 都是 `dsh --profile headless --dump-default-config` 里的真实条目（写错 id 会让\n# profile 组不起来，所以不要凭印象加）。\n# ============================================================================\n\n# ── headless 默认关掉、值班轮需要补开的（模型要用账号额度）──────────────────\n- id: credentials\n  disabled: false\n- id: authorization\n  disabled: false\n- id: deepseek-account\n  disabled: false\n- id: agent-default-model\n  config:\n    provider: deepseek-account\n    model: deepseek-flash\n\n# ── 命令执行 ────────────────────────────────────────────────────────────────\n- id: tool-bash\n  disabled: true\n- id: tool-pwsh\n  disabled: true\n- id: tool-jobs\n  disabled: true\n- id: jobs\n  disabled: true\n- id: tool-ralph\n  disabled: true\n\n# ── 文件系统：读 / 写 / 搜 —— 一个都不留 ────────────────────────────────────\n- id: tool-fs\n  disabled: true\n- id: tool-fs-search\n  disabled: true\n\n# ── 联网：B站 数据走 MCP，不需要它自己抓网页 ────────────────────────────────\n- id: tool-web\n  disabled: true\n- id: web-fetch-http\n  disabled: true\n- id: web-search-deepseek\n  disabled: true\n\n# ── 子代理 / 工作流：都能绕开工具限制 ───────────────────────────────────────\n- id: tool-subagent\n  disabled: true\n- id: tool-subagent-fork\n  disabled: true\n- id: tool-subagent-control\n  disabled: true\n- id: tool-subagent-list-agents\n  disabled: true\n- id: subagent\n  disabled: true\n- id: subagent-fork-in-process\n  disabled: true\n- id: subagent-spawn-in-process\n  disabled: true\n- id: workflow-ptc\n  disabled: true\n- id: ptc-runtime\n  disabled: true\n- id: tool-workflow\n  disabled: true\n\n# ── 技能：会读文件 ──────────────────────────────────────────────────────────\n- id: skill\n  disabled: true\n- id: skill-filesystem\n  disabled: true\n- id: skill-badge\n  disabled: true\n- id: tool-skill\n  disabled: true\n\n# ── 自动读 AGENTS.md（会把上级目录的私人设定塞进上下文）──────────────────────\n- id: agent-instructions\n  disabled: true\n\n# ── 装插件 / 热重载 / 改配置 ────────────────────────────────────────────────\n- id: tool-plugin-manager\n  disabled: true\n- id: plugin-manager\n  disabled: true\n- id: hmr\n  disabled: true\n\n# ── 目标循环 / 计划模式 / 待办 ──────────────────────────────────────────────\n- id: goal\n  disabled: true\n- id: command-goal\n  disabled: true\n- id: tool-goal\n  disabled: true\n- id: goal-round-driver\n  disabled: true\n- id: plan-mode\n  disabled: true\n- id: tool-todo\n  disabled: true\n\n# ── MCP 资源读取 ────────────────────────────────────────────────────────────\n- id: mcp-resources\n  disabled: true\n"
    },
